import re

def parse_simple_yaml(text):
    data = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            i += 1
            continue
        if ":" in line:
            parts = line.split(":", 1)
            key = parts[0].strip()
            val_str = parts[1].strip()
            if not val_str:
                # check if next lines are a list or dict
                sub_list = []
                j = i + 1
                while j < len(lines):
                    next_line = lines[j]
                    if not next_line.strip() or next_line.strip().startswith("#"):
                        j += 1
                        continue
                    indent = len(next_line) - len(next_line.lstrip())
                    if indent == 0:
                        break
                    if next_line.strip().startswith("-"):
                        # element of list
                        item_str = next_line.strip()[1:].strip()
                        if item_str.startswith("-"):
                            # nested list element
                            # read two item tuple
                            sub_item = [item_str[1:].strip()]
                            j += 1
                            if j < len(lines) and lines[j].strip().startswith("-"):
                                sub_item.append(lines[j].strip()[1:].strip())
                                j += 1
                            sub_list.append(sub_item)
                            continue
                        else:
                            sub_list.append(item_str)
                    j += 1
                data[key] = sub_list
                i = j
                continue
            else:
                # parse primitive
                val = parse_val(val_str)
                data[key] = val
        i += 1
    return data

def parse_val(v):
    v = v.strip()
    if v in ("null", "Null", "~", "None", ""):
        return None
    if v in ("true", "True", "true"):
        return True
    if v in ("false", "False", "false"):
        return False
    if (v.startswith("'") and v.endswith("'")) or (v.startswith('"') and v.endswith('"')):
        return v[1:-1]
    if v == "{}":
        return {}
    if v == "[]":
        return []
    try:
        if "." in v:
            return float(v)
        return int(v)
    except ValueError:
        return v

with open("/tmp/marmite_dump_all/initsite/marmite.yaml") as f:
    text = f.read()

parsed = parse_simple_yaml(text)
print("Parsed config keys count:", len(parsed))
print("Menu:", parsed.get("menu"))
print("Name:", parsed.get("name"))
print("Https:", parsed.get("https"))
PYEOF"}

