import re

def parse_yaml(text):
    if not text or not text.strip():
        return {}
    text = text.strip()
    if text.startswith("{") and text.endswith("}"):
        # inline dict
        return parse_inline_dict(text)

    lines = text.splitlines()
    root = {}

    def parse_block(lines, base_indent=0):
        res = {}
        i = 0
        while i < len(lines):
            line = lines[i]
            if not line.strip() or line.strip().startswith("#"):
                i += 1
                continue
            indent = len(line) - len(line.lstrip())
            if indent < base_indent:
                break

            stripped = line.strip()
            if ":" in stripped:
                colon_pos = stripped.find(":")
                key = stripped[:colon_pos].strip()
                val_part = stripped[colon_pos+1:].strip()

                if val_part:
                    res[key] = parse_value(val_part)
                    i += 1
                else:
                    # check block under key
                    block_lines = []
                    j = i + 1
                    sub_indent = None
                    while j < len(lines):
                        next_line = lines[j]
                        if not next_line.strip() or next_line.strip().startswith("#"):
                            j += 1
                            continue
                        next_indent = len(next_line) - len(next_line.lstrip())
                        if sub_indent is None:
                            if next_indent <= indent:
                                break
                            sub_indent = next_indent
                        elif next_indent < sub_indent:
                            break
                        block_lines.append(next_line)
                        j += 1

                    # determine if block is list or dict
                    if block_lines and block_lines[0].lstrip().startswith("-"):
                        res[key] = parse_yaml_list(block_lines, sub_indent)
                    else:
                        res[key] = parse_block(block_lines, sub_indent or (indent + 2))
                    i = j
            else:
                i += 1
        return res

    def parse_yaml_list(lines, base_indent):
        items = []
        i = 0
        while i < len(lines):
            line = lines[i]
            if not line.strip() or line.strip().startswith("#"):
                i += 1
                continue
            stripped = line.strip()
            if stripped.startswith("-"):
                item_content = stripped[1:].strip()
                if item_content.startswith("-"):
                    # nested list item like "- - Tags"
                    # collect lines for this list item
                    sub_item_lines = [line[line.find("-")+1:]]
                    j = i + 1
                    while j < len(lines):
                        nxt = lines[j]
                        if not nxt.strip() or nxt.strip().startswith("#"):
                            j += 1
                            continue
                        nxt_strip = nxt.strip()
                        if nxt_strip.startswith("-") and len(nxt) - len(nxt.lstrip()) == base_indent:
                            break
                        sub_item_lines.append(nxt)
                        j += 1
                    items.append(parse_yaml_list(sub_item_lines, base_indent + 2))
                    i = j
                elif ":" in item_content:
                    # list item is a dict
                    sub_lines = [line[line.find("-")+1:]]
                    j = i + 1
                    while j < len(lines):
                        nxt = lines[j]
                        if not nxt.strip():
                            j += 1
                            continue
                        if nxt.strip().startswith("-"):
                            break
                        sub_lines.append(nxt)
                        j += 1
                    items.append(parse_block(sub_lines, base_indent + 2))
                    i = j
                else:
                    items.append(parse_value(item_content))
                    i += 1
            else:
                i += 1
        return items

    return parse_block(lines, 0)

def parse_inline_dict(text):
    text = text.strip()[1:-1].strip()
    if not text:
        return {}
    res = {}
    for part in text.split(","):
        if ":" in part:
            k, v = part.split(":", 1)
            res[k.strip()] = parse_value(v.strip())
    return res

def parse_value(v):
    v = v.strip()
    if v in ("null", "Null", "~", "None", ""):
        return None
    if v in ("true", "True", "TRUE"):
        return True
    if v in ("false", "False", "FALSE"):
