                # Lookahead for list or sub-dict
                sub_lines = []
                j = i + 1
                while j < len(lines):
                    next_line = lines[j]
                    if not next_line.strip() or next_line.strip().startswith("#"):
                        j += 1
                        continue
                    indent = len(next_line) - len(next_line.lstrip())
                    if indent == 0:
                        break
                    sub_lines.append(next_line)
                    j += 1

