import os
import re
import html
import datetime
import urllib.parse
import json
import logger
import embedded_data

def slugify(text):
    if not text:
        return ""
    text = str(text).lower()
    text = re.sub(r'[^\w\s-]', '', text)
    text = re.sub(r'[\s_]+', '-', text)
    return text.strip('-')

class TemplateEngine:
    def __init__(self, templates_dir=None):
        self.templates_dir = templates_dir
        self.templates = dict(embedded_data.DEFAULT_TEMPLATES)
        if templates_dir and os.path.isdir(templates_dir):
            self.load_custom_templates(templates_dir)

    def load_custom_templates(self, custom_dir):
        for fname in os.listdir(custom_dir):
            fpath = os.path.join(custom_dir, fname)
            if os.path.isfile(fpath):
                with open(fpath, "r", encoding="utf-8") as f:
                    self.templates[fname] = f.read()

    def render(self, template_name, context):
        if template_name not in self.templates:
            logger.error("templates", f"Template {template_name} not found")
            return ""

        tmpl_src = self.templates[template_name]

        m_ext = re.search(r'\{%\s*extends\s*["\'](.*?)["\']\s*%\}', tmpl_src)
        if m_ext:
            parent_name = m_ext.group(1)
            parent_src = self.templates.get(parent_name, "")

            child_blocks = self._extract_blocks(tmpl_src)
            rendered_parent = self._replace_blocks(parent_src, child_blocks)
            return self._evaluate(rendered_parent, context)
        else:
            return self._evaluate(tmpl_src, context)

    def _extract_blocks(self, src):
        blocks = {}
        pattern = r'\{%\s*block\s+(\w+)\s*%\} (.*?)\{%\s*endblock(?:\s+\1)?\s*%\}'
        for m in re.finditer(pattern, src, re.DOTALL):
            blocks[m.group(1)] = m.group(2)
        return blocks

    def _replace_blocks(self, parent_src, child_blocks):
        def replacer(m):
            block_name = m.group(1)
            parent_content = m.group(2)
            if block_name in child_blocks:
                return child_blocks[block_name]
            return parent_content

        pattern = r'\{%\s*block\s+(\w+)\s*%\} (.*?)\{%\s*endblock(?:\s+\1)?\s*%\}'
        return re.sub(pattern, replacer, parent_src, flags=re.DOTALL)

    def _evaluate(self, src, context):
        def replace_include(m):
            inc_name = m.group(1)
            if inc_name in self.templates:
                return self._evaluate(self.templates[inc_name], context)
            return ""

        src = re.sub(r'\{%\s*include\s*["\'](.*?)["\'](?:\s+ignore missing)?\s*%\}', replace_include, src)
        return self._eval_tokens(src, dict(context))

    def _eval_tokens(self, src, ctx):
        def replace_url_for(m):
            params_str = m.group(1)
            path = ""
            abs_url = False
            m_path = re.search(r'path\s*=\s*(?:["\'](.*?)["\']|([\w\.-]+))', params_str)
            if m_path:
                path = m_path.group(1) or m_path.group(2) or ""
            if "abs=true" in params_str:
                abs_url = True

            site = ctx.get("site", {})
            site_url = site.get("url", "") if isinstance(site, dict) else getattr(site, "url", "")

            if abs_url and site_url:
                base = site_url.rstrip("/")
                return f"{base}/{path.lstrip('/')}"
            else:
                return f"/{path.lstrip('/')}"

        src = re.sub(r'\{\{\s*url_for\((.*?)\)\s*\}\}', replace_url_for, src)

        def replace_expr(m):
            expr = m.group(1).strip()
            return str(self._eval_expr(expr, ctx))

        output = []
        lines = src.splitlines(keepends=True)
        i = 0
        while i < len(lines):
            line = lines[i]
            m_for = re.search(r'\{%\s*for\s+(\w+)(?:,\s*(\w+))?\s+in\s+(.*?)\s*%\}', line)
            m_if = re.search(r'\{%\s*if\s+(.*?)\s*%\}', line)
            m_set = re.search(r'\{%\s*set\s+(\w+)\s*=\s*(.*?)\s*%\}', line)

            if m_set:
                var_name = m_set.group(1)
                val_expr = m_set.group(2)
                ctx[var_name] = self._eval_expr(val_expr, ctx)
                i += 1
            elif m_for:
                var1 = m_for.group(1)
                var2 = m_for.group(2)
                iter_expr = m_for.group(3)

                loop_lines = []
                j = i + 1
                depth = 1
                while j < len(lines):
                    if "{% for " in lines[j]:
                        depth += 1
                    elif "{% endfor %}" in lines[j] or "{%- endfor %}" in lines[j] or "{%- endfor -%}" in lines[j]:
                        depth -= 1
                        if depth == 0:
                            break
                    loop_lines.append(lines[j])
                    j += 1

                items = self._eval_expr(iter_expr, ctx) or []
                loop_src = "".join(loop_lines)

                for item in items:
                    sub_ctx = dict(ctx)
                    if var2:
                        sub_ctx[var1] = item[0] if len(item) > 0 else None
                        sub_ctx[var2] = item[1] if len(item) > 1 else None
                    else:
                        sub_ctx[var1] = item
                    output.append(self._eval_tokens(loop_src, sub_ctx))
                i = j + 1
            elif m_if:
                cond_expr = m_if.group(1)
                if_true_lines = []
                else_lines = []
                in_else = False
                j = i + 1
                depth = 1
                while j < len(lines):
                    if "{% if " in lines[j]:
                        depth += 1
                    elif "{% endif %}" in lines[j] or "{%- endif %}" in lines[j] or "{%- endif -%}" in lines[j]:
                        depth -= 1
                        if depth == 0:
                            break
                    elif depth == 1 and ("{% else %}" in lines[j] or "{%- else %}" in lines[j]):
                        in_else = True
                        j += 1
                        continue

                    if in_else:
                        else_lines.append(lines[j])
                    else:
                        if_true_lines.append(lines[j])
                    j += 1

                cond_val = self._eval_cond(cond_expr, ctx)
                if cond_val:
                    output.append(self._eval_tokens("".join(if_true_lines), ctx))
                else:
                    output.append(self._eval_tokens("".join(else_lines), ctx))
                i = j + 1
            else:
                line_eval = re.sub(r'\{\{\s*(.*?)\s*\}\}', replace_expr, line)
                output.append(line_eval)
                i += 1

        return "".join(output)

    def _eval_expr(self, expr, ctx):
        expr = expr.strip()
        if not expr:
            return ""

        if "|" in expr:
            parts = [p.strip() for p in expr.split("|")]
            val = self._eval_simple_expr(parts[0], ctx)
            for f in parts[1:]:
                val = self._apply_filter(val, f, ctx)
            return val
        else:
            return self._eval_simple_expr(expr, ctx)

    def _eval_simple_expr(self, expr, ctx):
        if expr == "true" or expr == "True":
            return True
        if expr == "false" or expr == "False":
            return False
        if expr == "null" or expr == "None":
            return None
        if (expr.startswith("'") and expr.endswith("'")) or (expr.startswith('"') and expr.endswith('"')):
            return expr[1:-1]
        try:
            return int(expr)
        except ValueError:
            pass

        parts = expr.split(".")
        val = ctx
        for p in parts:
            if isinstance(val, dict):
                val = val.get(p)
            elif hasattr(val, p):
                val = getattr(val, p)
            else:
                return ""
        return val if val is not None else ""

    def _eval_cond(self, expr, ctx):
        expr = expr.strip()
        if " is defined" in expr:
            var = expr.replace(" is defined", "").strip()
            return var in ctx and ctx[var] is not None
        if " is not defined" in expr:
            var = expr.replace(" is not defined", "").strip()
